      if (c && (c.pending || now - c.t < ttl)) { if (c.pending) (c.waiters = c.waiters || new Set()).add(this); return c.val !== undefined ? c.val : def; }
      const entry = { t: now, pending: true, val: c ? c.val : undefined, waiters: new Set([this]) };
